def duplicate_evaluation(evaluation_id):
    row = get_evaluation(evaluation_id)
    if not row:
        return None
    _, name, organization, evaluator, _, payload_json = row
    try:
        payload = json.loads(payload_json)
        copy_name = f"{name} (cópia)"
        payload["evaluation_name"] = copy_name
        now = datetime.now().isoformat(timespec="seconds")
        with db_connect() as conn:
            cur = conn.execute(
                """
                INSERT INTO evaluations
                (name, organization, evaluator, created_at, updated_at, payload)
                VALUES (?, ?, ?, ?, ?, ?)
                """,
                (copy_name, organization, evaluator, now, now, json.dumps(payload, ensure_ascii=False)),
            )
            conn.commit()
            new_id = cur.lastrowid
        return new_id
    except (sqlite3.Error, OSError, json.JSONDecodeError) as exc:
        st.error(f"Não foi possível duplicar a avaliação: {exc}")
        return None


def collect_payload():
    payload = {
        "evaluation_name": st.session_state.get("evaluation_name", ""),
        "organization": st.session_state.get("organization", ""),
        "evaluator": st.session_state.get("evaluator", ""),
        "included_areas": {},
        "targets": {},
        "responses": {},
        "notes": {},
    }

    for area in QUESTION_AREAS:
        aid = area["id"]
        payload["included_areas"][aid] = st.session_state.get(f"include_{aid}", True)
        payload["targets"][aid] = st.session_state.get(f"target_{aid}", 3.0)

        for q in area["questions"]:
            qid = q["id"]
            payload["responses"][qid] = st.session_state.get(f"q_{qid}", "Não avaliado")
            payload["notes"][qid] = st.session_state.get(f"obs_{qid}", "")

    return payload


def payload_hash(payload):
    serialized = json.dumps(payload, ensure_ascii=False, sort_keys=True, default=str)
    return hashlib.sha256(serialized.encode("utf-8")).hexdigest()


def save_evaluation():
    """Salva a avaliação atual no SQLite e retorna True em caso de sucesso."""
    try:
        payload = collect_payload()
        name = payload["evaluation_name"].strip() or "Avaliação sem nome"
        organization = payload["organization"].strip()
        evaluator = payload["evaluator"].strip()
        now = datetime.now().isoformat(timespec="seconds")

        with db_connect() as conn:
            evaluation_id = st.session_state.get("evaluation_id")
            if evaluation_id:
                conn.execute(
                    """
                    UPDATE evaluations
                    SET name = ?, organization = ?, evaluator = ?, updated_at = ?, payload = ?
                    WHERE id = ?
                    """,
                    (
                        name, organization, evaluator, now,
                        json.dumps(payload, ensure_ascii=False), evaluation_id,
                    ),
                )
            else:
                cur = conn.execute(
                    """
                    INSERT INTO evaluations
                    (name, organization, evaluator, created_at, updated_at, payload)
                    VALUES (?, ?, ?, ?, ?, ?)
                    """,
                    (
                        name, organization, evaluator, now, now,
                        json.dumps(payload, ensure_ascii=False),
                    ),
                )
                st.session_state["evaluation_id"] = cur.lastrowid
            conn.commit()

        st.session_state["saved_payload_hash"] = payload_hash(payload)
        st.session_state["last_saved_at"] = now
        st.session_state.pop("db_error", None)
        return True
    except (sqlite3.Error, OSError, ValueError) as exc:
        st.error(f"Não foi possível salvar a avaliação: {exc}")
        return False


def load_evaluation(evaluation_id):
    row = get_evaluation(evaluation_id)
    if not row:
        st.error("Não foi possível carregar a avaliação selecionada.")
        return False

    _, name, organization, evaluator, updated_at, payload_json = row
    try:
        payload = json.loads(payload_json)
    except json.JSONDecodeError as exc:
        st.error(f"Os dados da avaliação estão corrompidos: {exc}")
        return False

    st.session_state["evaluation_id"] = evaluation_id
    st.session_state["evaluation_name"] = payload.get("evaluation_name", name)
    st.session_state["organization"] = payload.get("organization", organization or "")
    st.session_state["evaluator"] = payload.get("evaluator", evaluator or "")

    for area in QUESTION_AREAS:
        aid = area["id"]
        st.session_state[f"include_{aid}"] = payload.get("included_areas", {}).get(aid, True)
        st.session_state[f"target_{aid}"] = float(payload.get("targets", {}).get(aid, 3.0))
        for q in area["questions"]:
            qid = q["id"]
            st.session_state[f"q_{qid}"] = payload.get("responses", {}).get(qid, "Não avaliado")
            st.session_state[f"obs_{qid}"] = payload.get("notes", {}).get(qid, "")

    st.session_state["saved_payload_hash"] = payload_hash(payload)
    st.session_state["last_saved_at"] = updated_at
    st.session_state.pop("pdf_bytes", None)
    st.session_state.pop("pdf_hash", None)
    return True


def new_evaluation():
    prefixes = ("q_", "obs_", "include_", "target_")
    to_delete = [
        key
        for key in st.session_state.keys()
        if key.startswith(prefixes)
        or key
        in {
            "evaluation_id",
            "evaluation_name",
            "organization",
            "evaluator",
            "report_ready",
            "saved_payload_hash",
            "last_saved_at",
            "pdf_bytes",
            "pdf_hash",
        }
    ]
    for key in to_delete:
        del st.session_state[key]


def option_score(question, selected_label):
    for label, score in question["options"]:
        if label == selected_label:
            return score
    return None


def dependency_is_active(question):
    dep = question.get("depends_on")
    if not dep:
        return True

    dep_question = QUESTIONS_BY_ID.get(dep)
    if not dep_question:
        return False

    dep_value = st.session_state.get(f"q_{dep}", "Não avaliado")
    score = option_score(dep_question, dep_value)
    return score is not None and score > 0


def classify_area(score, target, critical_count):
    if score is None:
        return "Sem dados"
    gap = score - target
    if critical_count > 0:
        return "Crítico"
    if gap >= 0:
        return "Adequado"
    if gap >= -1:
        return "Atenção"
    return "Insuficiente"


def calculate_results():
    area_results = []
    critical_findings = []
    pending_total = 0
    answered_total = 0
    applicable_total = 0

    for area in QUESTION_AREAS:
        aid = area["id"]
        included = st.session_state.get(f"include_{aid}", True)
        target = float(st.session_state.get(f"target_{aid}", 3.0))

        if not included:
            area_results.append(
                {
                    "area_id": aid,
                    "area": area["short"],
                    "included": False,
                    "score": None,
                    "percent": None,
                    "target": target,
                    "gap": None,
                    "status": "Fora do escopo",
                    "critical_count": 0,
                    "answered": 0,
                    "pending": 0,
                    "details": [],
                }
            )
            continue

        scores = []
        details = []
        critical_count = 0
        pending = 0

        for q in area["questions"]:
            if not dependency_is_active(q):
                continue

            selected = st.session_state.get(f"q_{q['id']}", "Não avaliado")
            note = st.session_state.get(f"obs_{q['id']}", "")
            score = option_score(q, selected)

            if selected == "Não avaliado":
                pending += 1
                pending_total += 1
            elif selected != "Não se aplica":
                applicable_total += 1
                if score is not None:
                    answered_total += 1

            is_critical_finding = bool(q.get("critical")) and score is not None and score <= 1
            if is_critical_finding:
                critical_count += 1
                critical_findings.append(
                    {
                        "area": area["short"],
                        "question": q["text"],
                        "answer": selected,
                        "note": note,
                    }
                )

            if score is not None:
                scores.append(score)

            details.append(
                {
                    "id": q["id"],
                    "question": q["text"],
                    "answer": selected,
                    "score": score,
                    "note": note,
                    "critical": bool(q.get("critical")),
                    "critical_finding": is_critical_finding,
                }
            )

        score = sum(scores) / len(scores) if scores else None
        percent = (score / 5.0 * 100.0) if score is not None else None
        gap = (score - target) if score is not None else None
        status = classify_area(score, target, critical_count)

        area_results.append(
            {
                "area_id": aid,
                "area": area["short"],
                "included": True,
                "score": score,
                "percent": percent,
                "target": target,
                "gap": gap,
                "status": status,
                "critical_count": critical_count,
                "answered": len(scores),
                "pending": pending,
                "details": details,
            }
        )

    included_with_scores = [r for r in area_results if r["included"] and r["score"] is not None]
    overall_score = (
        sum(r["score"] for r in included_with_scores) / len(included_with_scores)
        if included_with_scores
        else None
    )
    overall_percent = (overall_score / 5.0 * 100.0) if overall_score is not None else None

    return {
        "areas": area_results,
        "overall_score": overall_score,
        "overall_percent": overall_percent,
        "critical_findings": critical_findings,
        "pending_total": pending_total,
        "answered_total": answered_total,
        "applicable_total": applicable_total,
    }


def render_question(question):
    if not dependency_is_active(question):
        return

    labels = [label for label, _ in question["options"]]
    key = f"q_{question['id']}"

    if key not in st.session_state:
        st.session_state[key] = "Não avaliado"

    try:
        current_index = labels.index(st.session_state[key])
    except ValueError:
        current_index = 0

    critical_tag = " **[CRÍTICO]**" if question.get("critical") else ""
    st.markdown(f"**{question['id']} — {question['text']}**{critical_tag}")

    st.radio(
        label=question["text"],
        options=labels,
        index=current_index,
        key=key,
        label_visibility="collapsed",
    )
    st.text_input(
        "Observação (opcional)",
        key=f"obs_{question['id']}",
        placeholder="Contexto, evidência, pendência ou observação...",
    )
    st.divider()


def render_area(area):
    aid = area["id"]
    st.header(area["title"])
    st.caption(area["description"])

    c1, c2 = st.columns([1, 1])
    with c1:
        st.checkbox(
            "Incluir esta área na avaliação",
            value=st.session_state.get(f"include_{aid}", True),
            key=f"include_{aid}",
        )
    with c2:
        st.slider(
            "Nível-alvo da área",
            min_value=0.0,
            max_value=5.0,
            value=float(st.session_state.get(f"target_{aid}", 3.0)),
            step=0.5,
            key=f"target_{aid}",
            help="Nível desejado para o contexto avaliado. Não é uma meta universal.",
        )

    if not st.session_state.get(f"include_{aid}", True):
        st.info("Área fora do escopo desta avaliação.")
        return

    for q in area["questions"]:
        render_question(q)



