def format_num(value, digits=1):
    if value is None:
        return "—"
    return f"{value:.{digits}f}"


def report_table_dataframe(results):
    rows = []
    for r in results["areas"]:
        if not r["included"]:
            rows.append(
                {
                    "Área": r["area"],
                    "Nível atual": "—",
                    "Nível-alvo": "—",
                    "Gap": "—",
                    "Índice": "—",
                    "Situação": "Fora do escopo",
                    "Críticos": 0,
                }
            )
            continue

        rows.append(
            {
                "Área": r["area"],
                "Nível atual": format_num(r["score"]),
                "Nível-alvo": format_num(r["target"]),
                "Gap": format_num(r["gap"]),
                "Índice": f"{r['percent']:.0f}%" if r["percent"] is not None else "—",
                "Situação": r["status"],
                "Críticos": r["critical_count"],
            }
        )
    return pd.DataFrame(rows)


def safe_text(value):
    """Escapa texto antes de enviá-lo ao parser XML/HTML do ReportLab Paragraph."""
    return escape(str(value or ""))


def safe_filename(value):
    value = str(value or "operacao-ti").strip().lower()
    value = re.sub(r"[^a-z0-9._-]+", "-", value, flags=re.IGNORECASE)
    return value.strip("-._") or "operacao-ti"


def results_to_csv(results):
    rows = []
    for area in results["areas"]:
        if not area["included"]:
            rows.append({
                "Área": area["area"], "ID": "", "Pergunta": "",
                "Resposta": "Fora do escopo", "Nota": "", "Crítico": "", "Observação": ""
            })
            continue
        for d in area["details"]:
            rows.append({
                "Área": area["area"],
                "ID": d["id"],
                "Pergunta": d["question"],
                "Resposta": d["answer"],
                "Nota": "" if d["score"] is None else d["score"],
                "Crítico": "Sim" if d["critical_finding"] else "Não",
                "Observação": d["note"],
            })
    return pd.DataFrame(rows).to_csv(index=False).encode("utf-8-sig")


def generate_pdf(results):
    buffer = io.BytesIO()
    doc = SimpleDocTemplate(
        buffer,
        pagesize=A4,
        rightMargin=1.4 * cm,
        leftMargin=1.4 * cm,
        topMargin=1.5 * cm,
        bottomMargin=1.5 * cm,
    )

    styles = getSampleStyleSheet()
    title_style = ParagraphStyle(
        "CustomTitle",
        parent=styles["Title"],
        alignment=TA_CENTER,
        fontSize=18,
        leading=22,
        spaceAfter=14,
    )
    h1 = styles["Heading1"]
    h2 = styles["Heading2"]
    body = styles["BodyText"]
    body.fontSize = 9
    body.leading = 12

    story = []
    story.append(Paragraph(APP_TITLE, title_style))

    organization = st.session_state.get("organization", "").strip() or "Não informado"
    evaluator = st.session_state.get("evaluator", "").strip() or "Não informado"
    evaluation_name = st.session_state.get("evaluation_name", "").strip() or "Avaliação sem nome"

    meta = [
        ["Avaliação", Paragraph(safe_text(evaluation_name), body)],
        ["Organização", Paragraph(safe_text(organization), body)],
        ["Responsável", Paragraph(safe_text(evaluator), body)],
        ["Data", datetime.now().strftime("%d/%m/%Y %H:%M")],
    ]
    meta_table = Table(meta, colWidths=[3.5 * cm, 13.0 * cm])
    meta_table.setStyle(
        TableStyle(
            [
                ("FONTNAME", (0, 0), (-1, -1), "Helvetica"),
                ("FONTSIZE", (0, 0), (-1, -1), 9),
                ("VALIGN", (0, 0), (-1, -1), "TOP"),
                ("GRID", (0, 0), (-1, -1), 0.3, colors.grey),
                ("BACKGROUND", (0, 0), (0, -1), colors.lightgrey),
            ]
        )
    )
    story.append(meta_table)
    story.append(Spacer(1, 12))

    story.append(Paragraph("Resumo Executivo", h1))
    if results["overall_score"] is None:
        story.append(Paragraph("Não há respostas suficientes para calcular o resultado geral.", body))
    else:
        story.append(
            Paragraph(
                f"Índice geral de estruturação: <b>{results['overall_percent']:.0f}%</b> "
                f"(nível médio {results['overall_score']:.1f} de 5).",
                body,
            )
        )
    story.append(
        Paragraph(
            "O índice geral é apenas uma visão consolidada. A interpretação deve priorizar "
            "os gaps por área e as constatações críticas.",
            body,
        )
    )
    story.append(Spacer(1, 8))

    summary_data = [
        ["Área", "Atual", "Alvo", "Gap", "Índice", "Situação", "Críticos"]
    ]
    for r in results["areas"]:
        if not r["included"]:
            summary_data.append([r["area"], "-", "-", "-", "-", "Fora do escopo", "0"])
        else:
            summary_data.append(
                [
                    r["area"],
                    format_num(r["score"]),
                    format_num(r["target"]),
                    format_num(r["gap"]),
                    f"{r['percent']:.0f}%" if r["percent"] is not None else "-",
                    r["status"],
                    str(r["critical_count"]),
                ]
            )

    summary_table = Table(
        summary_data,
        repeatRows=1,
        colWidths=[5.0 * cm, 1.4 * cm, 1.4 * cm, 1.2 * cm, 1.4 * cm, 2.8 * cm, 1.4 * cm],
    )
    summary_table.setStyle(
        TableStyle(
            [
                ("FONTNAME", (0, 0), (-1, -1), "Helvetica"),
                ("FONTSIZE", (0, 0), (-1, -1), 7.5),
                ("BACKGROUND", (0, 0), (-1, 0), colors.lightgrey),
                ("GRID", (0, 0), (-1, -1), 0.25, colors.grey),
                ("VALIGN", (0, 0), (-1, -1), "TOP"),
            ]
        )
    )
    story.append(summary_table)
    story.append(Spacer(1, 12))

    story.append(Paragraph("Constatações Críticas", h1))
    if not results["critical_findings"]:
        story.append(Paragraph("Nenhuma constatação crítica foi identificada nas respostas preenchidas.", body))
    else:
        for item in results["critical_findings"]:
            txt = (
                f"<b>{safe_text(item['area'])}</b> — {safe_text(item['question'])}<br/>"
                f"Resposta: {safe_text(item['answer'])}"
            )
            if item["note"]:
                txt += f"<br/>Observação: {safe_text(item['note'])}"
            story.append(Paragraph(txt, body))
            story.append(Spacer(1, 6))

    story.append(PageBreak())
    story.append(Paragraph("Detalhamento por Área", h1))

    for r in results["areas"]:
        story.append(Paragraph(safe_text(r["area"]), h2))

        if not r["included"]:
            story.append(Paragraph("Área fora do escopo desta avaliação.", body))
            story.append(Spacer(1, 8))
            continue

        if r["score"] is not None:
            story.append(
                Paragraph(
                    f"Atual: <b>{r['score']:.1f}</b> | "
                    f"Alvo: <b>{r['target']:.1f}</b> | "
                    f"Gap: <b>{r['gap']:.1f}</b> | "
                    f"Situação: <b>{r['status']}</b>",
                    body,
                )
            )
        else:
            story.append(Paragraph("Sem respostas suficientes para cálculo.", body))

        story.append(Spacer(1, 6))
        detail_data = [["ID", "Pergunta", "Resposta", "Nota", "Observação"]]
        for d in r["details"]:
            detail_data.append(
                [
                    d["id"],
                    Paragraph(safe_text(d["question"]), body),
                    Paragraph(safe_text(d["answer"]), body),
                    "-" if d["score"] is None else str(d["score"]),
                    Paragraph(safe_text(d["note"]), body),
                ]
            )

        if len(detail_data) > 1:
            detail_table = Table(
                detail_data,
                repeatRows=1,
                colWidths=[1.1 * cm, 6.1 * cm, 4.4 * cm, 1.0 * cm, 3.6 * cm],
            )
            detail_table.setStyle(
                TableStyle(
                    [
                        ("FONTNAME", (0, 0), (-1, -1), "Helvetica"),
                        ("FONTSIZE", (0, 0), (-1, -1), 7),
                        ("BACKGROUND", (0, 0), (-1, 0), colors.lightgrey),
                        ("GRID", (0, 0), (-1, -1), 0.2, colors.grey),
                        ("VALIGN", (0, 0), (-1, -1), "TOP"),
                    ]
                )
            )
            story.append(detail_table)

        story.append(Spacer(1, 12))

    story.append(PageBreak())
    story.append(Paragraph("Metodologia", h1))
    methodology = (
        "Este diagnóstico utiliza um modelo próprio inicial de avaliação da Operação de TI. "
        "As respostas são convertidas em uma escala de 0 a 5: 0 inexistente; 1 informal ou "
        "inadequado; 2 parcial; 3 implementado/definido; 4 controlado; 5 medido e melhorado. "
        "Questões marcadas como críticas, quando avaliadas nos níveis 0 ou 1, geram uma "
        "constatação crítica independentemente da média. O nível-alvo é definido pelo avaliador "
        "conforme o contexto da organização. A metodologia não representa certificação ou "
        "avaliação oficial de COBIT, ITIL, ISO ou outro referencial e deverá ser calibrada "
        "posteriormente com literatura e validação prática."
    )
    story.append(Paragraph(methodology, body))


    story.append(Spacer(1, 14))
    story.append(Paragraph("Criado por", h1))
    author_contact = (
        "<b>Daniel Diehl</b><br/>"
        "E-mail: consultortiglobal@gmail.com<br/>"

    )
    story.append(Paragraph(author_contact, body))

    doc.build(story)
    buffer.seek(0)
    return buffer.getvalue()


