# -------------------------------------------------------------------
# Relatório
# -------------------------------------------------------------------
with tabs[-1]:
    st.header("Relatório")
    st.caption(
        "O relatório consolida apenas as áreas incluídas no escopo. "
        "'Não se aplica' não reduz a nota e 'Não avaliado' permanece pendente."
    )

    c1, c2 = st.columns(2)

    with c1:
        if st.button("Gerar relatório", type="primary", use_container_width=True):
            st.session_state["report_ready"] = True

    filename_org = safe_filename(st.session_state.get("organization", "") or "operacao-ti")
    filename = f"diagnostico-operacao-ti-{filename_org}.pdf"
    report_hash = payload_hash(collect_payload())

    if st.session_state.get("pdf_hash") != report_hash:
        st.session_state.pop("pdf_bytes", None)
        st.session_state.pop("pdf_hash", None)

    with c2:
        if st.button("Gerar relatório em PDF", use_container_width=True):
            try:
                st.session_state["pdf_bytes"] = generate_pdf(current_results)
                st.session_state["pdf_hash"] = report_hash
                st.success("PDF preparado. Clique em Baixar PDF.")
            except Exception as exc:
                st.error(f"Não foi possível gerar o PDF: {exc}")

    if "pdf_bytes" in st.session_state:
        st.download_button(
            "Baixar PDF",
            data=st.session_state["pdf_bytes"],
            file_name=filename,
            mime="application/pdf",
            use_container_width=True,
        )

    st.download_button(
        "Exportar respostas em CSV",
        data=results_to_csv(current_results),
        file_name=f"respostas-operacao-ti-{filename_org}.csv",
        mime="text/csv",
        use_container_width=True,
    )

    if st.session_state.get("report_ready", False):
        results = current_results

        if results["overall_score"] is None:
            st.warning("Ainda não há respostas suficientes para calcular o resultado geral.")
        else:
            m1, m2, m3 = st.columns(3)
            m1.metric("Índice geral", f"{results['overall_percent']:.0f}%")
            m2.metric("Nível médio", f"{results['overall_score']:.1f} / 5")
            m3.metric("Constatações críticas", len(results["critical_findings"]))

        st.subheader("Quadro de desempenho")
        st.dataframe(
            report_table_dataframe(results),
            use_container_width=True,
            hide_index=True,
        )

        st.subheader("Constatações críticas")
        if not results["critical_findings"]:
            st.success("Nenhuma constatação crítica identificada nas respostas preenchidas.")
        else:
            for finding in results["critical_findings"]:
                st.error(
                    f"**{finding['area']}** — {finding['question']}\n\n"
                    f"Resposta: **{finding['answer']}**"
                    + (f"\n\nObservação: {finding['note']}" if finding["note"] else "")
                )

        st.subheader("Detalhamento")
        for area_result in results["areas"]:
            label = f"{area_result['area']} — {area_result['status']}"
            with st.expander(label):
                if not area_result["included"]:
                    st.info("Área fora do escopo.")
                    continue

                if area_result["score"] is not None:
                    st.write(
                        f"**Atual:** {area_result['score']:.1f} | "
                        f"**Alvo:** {area_result['target']:.1f} | "
                        f"**Gap:** {area_result['gap']:.1f} | "
                        f"**Índice:** {area_result['percent']:.0f}%"
                    )

                rows = []
                for d in area_result["details"]:
                    rows.append(
                        {
                            "ID": d["id"],
                            "Pergunta": d["question"],
                            "Resposta": d["answer"],
                            "Nota": "—" if d["score"] is None else d["score"],
                            "Crítico": "Sim" if d["critical_finding"] else "",
                            "Observação": d["note"],
                        }
                    )
                st.dataframe(pd.DataFrame(rows), use_container_width=True, hide_index=True)

        st.info(
            "Metodologia inicial: escala própria de 0 a 5, comparação atual × alvo "
            "e alerta separado para constatações críticas. O índice geral não deve ser "
            "interpretado isoladamente como certificação ou maturidade oficial."
        )
